import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {validateSlideSummary} from '@/components/nyc-tron/ui/components/forge/slides/slide-model';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {useEditorBoundary} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useRef,useLayoutEffect,type ReactNode} from "react";
import {I18nManager,Pressable,FlatList,Text,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import {ToolButton,officeKey,type OfficeKeyEvent} from "@/components/nyc-tron/ui/components/forge/office/office-controls";
import {SlideThumbnail} from "@/components/nyc-tron/ui/components/forge/slides/SlideThumbnail";
import {SLIDE_DEFAULT_SIZE,gridColumns,gridMove,moveBlock,nextSelection,slideLabel,type SlideObject,type SlideSize,type SlideSummary} from "@/components/nyc-tron/ui/components/forge/slides/slide-model";
import {space,radius,border} from '@/components/nyc-tron/ui/tokens';

/** Props for {@linkcode SlideSorter}. Selection is controlled; actions render only when their callbacks are passed. */
export interface SlideSorterProps extends Omit<ViewProps,"children">,ScopedControlProps {
  readonly slides:readonly SlideSummary[];
  readonly selectedIds:readonly string[];
  readonly onSelectionChange:(ids:string[])=>void;
  /** Opens a slide in the editor (double press or Enter). */
  readonly onOpen?:(id:string)=>void;
  /**
   * Applies a new deck order after the selection was moved as a block. The
   * host turns it into engine moves (`planMoves` gives single from/to steps).
   */
  readonly onReorder?:(order:string[])=>void|Promise<unknown>;
  /** Deletes the selected slides. Not offered when it would delete every slide. */
  readonly onRemove?:(ids:string[])=>void|Promise<unknown>;
  readonly size?:SlideSize;
  readonly renderImage?:(src:string,object:SlideObject)=>ReactNode;
  /** Smallest thumbnail width in points; columns are fitted to the measured width. @default 160 */
  readonly minThumbnailWidth?:number;
  disabled?:boolean;
  className?:string;
  unstyled?:boolean;
}

const GAP=12;

/**
 * Slide sorter grid (J-02) with multiselect: a press selects one slide,
 * Cmd/Ctrl adds or removes, Shift selects a range, and "Select" mode makes
 * presses toggle on touch screens. The selection moves as a block to the
 * start, one place earlier or later, or the end. Arrow keys move focus in the
 * grid, Space toggles, Enter opens.
 */
export function SlideSorter({scope='SlideSorter',revision=0,...props}:SlideSorterProps){
 if(props.slides.length>10000||props.slides.reduce((n,s)=>n+s.objects.length,0)>100000||new Set(props.slides.map(s=>s.id)).size!==props.slides.length||props.selectedIds.some(id=>!props.slides.some(s=>s.id===id)))throw new RangeError('Invalid slide sorter roster');props.slides.forEach(validateSlideSummary);
 const identity=JSON.stringify(controlIdentity(scope,revision)),owner=useEditorBoundary([JSON.stringify([identity,props.disabled,props.disabledReason,props.slides.map(s=>s.id)])]),guard=useScopedControl(owner,props,!!props.disabled||props.disabledReason!==undefined);
 return <SlideSorterBody key={identity} {...props} boundary={owner} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onReorder={props.onReorder?(...args:Parameters<NonNullable<SlideSorterProps['onReorder']>>)=>guard.run('onReorder',h=>h.onReorder?.(...args)):undefined}
  onRemove={props.onRemove?(...args:Parameters<NonNullable<SlideSorterProps['onRemove']>>)=>guard.run('onRemove',h=>h.onRemove?.(...args)):undefined}
  onSelectionChange={(...args:Parameters<NonNullable<SlideSorterProps['onSelectionChange']>>)=>{guard.current()?.onSelectionChange?.(...args);}}
  onOpen={props.onOpen?(...args:Parameters<NonNullable<SlideSorterProps['onOpen']>>)=>{guard.current()?.onOpen?.(...args);}:undefined}
 />;
}
function SlideSorterBody({boundary,actionError,disabledReason,disabled=false,
  slides,selectedIds,onSelectionChange,onOpen,onReorder,onRemove,size=SLIDE_DEFAULT_SIZE,renderImage,minThumbnailWidth=160,
  className,unstyled=false,...rest
}:SlideSorterProps&{boundary:string;actionError?:string|null}){
  const styled=!unstyled;
  const [local,store]=useLocalStore(()=>({width:0,anchor:undefined as string|undefined,multi:false}));
  const refs=useRef(new Map<number,{focus?:()=>void}|null>());
  const order=slides.map(s=>s.id);
  const columns=gridColumns(local.width,minThumbnailWidth,GAP);
  const cell=local.width>0?Math.floor((local.width-GAP*(columns-1))/columns):minThumbnailWidth;
  const tileHeight=Math.ceil((cell-8)*size.height/size.width+40),list=useRef<FlatList<SlideSummary>|null>(null),scrollAnchor=useRef(0),pendingFocus=useRef<number|null>(null);
  useLayoutEffect(()=>{list.current?.scrollToOffset({offset:Math.floor(scrollAnchor.current/columns)*(tileHeight+GAP),animated:false});},[columns,tileHeight]);
  const selected=new Set(selectedIds);
  const count=selected.size;
  const indexes=order.map((id,i)=>selected.has(id)?i:-1).filter(i=>i>=0);
  const first=indexes[0]??-1,last=indexes.at(-1)??-1;
  const reorder=(to:number)=>{
    if(disabled||!onReorder||count===0)return;
    const next=moveBlock(order,selectedIds,to);
    if(next.some((id,i)=>id!==order[i]))void onReorder(next);
  };
  const pick=(id:string,mode:"replace"|"toggle"|"range")=>{
    if(disabled)return;
    const r=nextSelection(order,selectedIds,local.anchor,id,mode);
    store.set(s=>({...s,anchor:r.anchor}));
    onSelectionChange(r.selected);
  };
  const muted=joinClasses(styled&&"text-text-muted text-sm");
  return <View {...rest} accessibilityLabel="Slide sorter" {...{className:joinClasses("min-w-0",className)}}
    style={[{gap:space[2.5]},rest.style as object]}>
    <View style={{flexDirection:"row",alignItems:"center",gap:space[1],flexWrap:"wrap"}}>
      <ToolButton label="Select" checked={local.multi} styled={styled} accessibilityHint="Presses add or remove slides from the selection"
        onPress={()=>store.set(s=>({...s,multi:!s.multi}))}/>
      <Text accessibilityLiveRegion="polite" {...{className:muted}} style={{paddingHorizontal:space[1.5]}}>
        {count===0?"No slides selected":count===1?"1 slide selected":count+" slides selected"}
      </Text>
      {onReorder?<>
        <ToolButton label="Move to start" disabled={disabled||count===0||last<count} styled={styled} onPress={()=>reorder(0)}/>
        <ToolButton label="Move earlier" disabled={disabled||count===0||first<=0} styled={styled} onPress={()=>reorder(first-1)}/>
        <ToolButton label="Move later" disabled={disabled||count===0||last>=order.length-1} styled={styled} onPress={()=>reorder(first+1)}/>
        <ToolButton label="Move to end" disabled={disabled||count===0||first>=order.length-count} styled={styled} onPress={()=>reorder(order.length)}/>
      </>:null}
      {onRemove?<ToolButton label={count>1?"Delete "+count+" slides":"Delete slide"} disabled={disabled||count===0||count>=order.length}
        styled={styled} onPress={()=>void onRemove(order.filter(id=>selected.has(id)))}/>:null}
    </View>
    <FlatList ref={list} key={columns} numColumns={columns} data={slides} keyExtractor={slide=>slide.id} initialNumToRender={Math.max(6,columns*2)} windowSize={5} removeClippedSubviews={false}
      initialScrollIndex={Math.floor(scrollAnchor.current/columns)} getItemLayout={(_data,index)=>({length:tileHeight+GAP,offset:(tileHeight+GAP)*index,index})}
      onScroll={e=>{scrollAnchor.current=Math.max(0,Math.floor(e.nativeEvent.contentOffset.y/(tileHeight+GAP))*columns);}} scrollEventThrottle={32}
      onLayout={e=>store.set(s=>({...s,width:e.nativeEvent.layout.width}))} style={{maxHeight:640}} contentContainerStyle={{gap:GAP}} columnWrapperStyle={columns>1?{gap:GAP}:undefined}
      extraData={[selectedIds,disabled,local.multi]} renderItem={({item:slide,index})=>{

        const on=selected.has(slide.id);
        const onKeyDown=(e:OfficeKeyEvent)=>{
          const {key,shift,mod}=officeKey(e);
          const next=gridMove(index,key,columns,slides.length,I18nManager.isRTL);
          let handled=true;
          if(next!==undefined){
            const node=refs.current.get(next);if(node)node.focus?.();else{pendingFocus.current=next;list.current?.scrollToOffset({offset:Math.floor(next/columns)*(tileHeight+GAP),animated:false});}
            if(shift)pick(order[next]!,"range");
          }
          else if(key===" ")pick(slide.id,"toggle");
          else if(key==="Enter"&&onOpen)onOpen(slide.id);
          else if(mod&&key.toLowerCase()==="a")onSelectionChange([...order]);
          else handled=false;
          if(handled)(e as unknown as {preventDefault?:()=>void}).preventDefault?.();
        };
        return <View key={slide.id} style={{width:cell,height:tileHeight,gap:space[1]}}>
          <Pressable disabled={disabled} ref={node=>{refs.current.set(index,node as unknown as {focus?:()=>void}|null);if(node&&pendingFocus.current===index){(node as unknown as {focus?:()=>void}).focus?.();pendingFocus.current=null;}}}
            accessibilityRole="checkbox" accessibilityLabel={slideLabel(slide,index,slides.length)} accessibilityState={{checked:on}}
            accessibilityHint={onOpen?"Double tap to select. Use the open action to edit.":undefined}
            accessibilityActions={onOpen?[{name:"activate"},{name:"open",label:"Open slide"}]:[{name:"activate"}]}
            onAccessibilityAction={e=>{if(e.nativeEvent.actionName==="open")onOpen?.(slide.id);else pick(slide.id,"toggle");}}
            onPress={e=>{
              const n=(e as unknown as {nativeEvent?:{shiftKey?:boolean;metaKey?:boolean;ctrlKey?:boolean}}).nativeEvent??{};
              pick(slide.id,n.shiftKey?"range":n.metaKey||n.ctrlKey||local.multi?"toggle":"replace");
            }}
            {...{onKeyDown,onDoubleClick:onOpen?()=>onOpen(slide.id):undefined}}
            {...{className:joinClasses(styled&&"rounded-control border-2 focus-visible:ring-2 focus-visible:ring-focus",
              styled&&(on?"border-accent":"border-border"))}}
            style={{padding:space[0.5],overflow:"hidden"}}>
            <SlideThumbnail slide={slide} width={cell-8} size={size} renderImage={renderImage} styled={styled}/>
            {on?<View {...{className:joinClasses(styled&&"bg-accent")}}
              style={{position:"absolute",top:6,end:6,width:20,height:20,borderRadius:radius[10],alignItems:"center",justifyContent:"center"}}>
              <View {...{className:joinClasses(styled&&"border-surface-raised")}}
                style={{width:9,height:5,borderStartWidth:2,borderBottomWidth:border[2],transform:[{rotate:"-45deg"}],marginTop:-space[0.5]}}/>
            </View>:null}
          </Pressable>
          <Text {...{className:muted}} style={{fontVariant:["tabular-nums"],textAlign:"center"}}>{index+1}</Text>
        </View>;
      }}/>
  <ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/></View>;
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}

